  UNIQUE KEY `uk_learning_concept_blocks_order` (`concept_id`,`sort_order`),
  KEY `idx_learning_concept_blocks_concept` (`concept_id`,`is_visible`,`sort_order`),
  CONSTRAINT `fk_learning_concept_blocks_concept` FOREIGN KEY (`concept_id`) REFERENCES `learning_concepts` (`concept_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=599 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
