CREATE TABLE `learning_concept_details` (
  `concept_id` bigint NOT NULL,
  `detail_id` int NOT NULL,
  `relation_type` enum('PRIMARY','SECONDARY','PREREQUISITE') NOT NULL DEFAULT 'PRIMARY',
  `sort_order` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`concept_id`,`detail_id`),
  KEY `idx_learning_concept_details_detail` (`detail_id`,`relation_type`),
  CONSTRAINT `fk_learning_concept_details_concept` FOREIGN KEY (`concept_id`) REFERENCES `learning_concepts` (`concept_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_learning_concept_details_detail` FOREIGN KEY (`detail_id`) REFERENCES `quiz_category_details` (`detail_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
