DROP TABLE IF EXISTS `learning_concepts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learning_concepts` (
  `concept_id` bigint NOT NULL AUTO_INCREMENT,
  `topic_id` int DEFAULT NULL,
  `investment_level_id` int NOT NULL,
  `concept_code` varchar(120) NOT NULL,
  `slug` varchar(160) NOT NULL,
  `title` varchar(255) NOT NULL,
  `summary` text,
  `learning_objectives` json DEFAULT NULL,
  `prerequisite_text` text,
  `estimated_minutes` int NOT NULL DEFAULT '5',
  `sort_order` int NOT NULL DEFAULT '1',
  `thumbnail_url` varchar(500) DEFAULT NULL,
  `status` enum('DRAFT','REVIEW','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
  `source_type` enum('MANUAL','AI_GENERATED','AI_ASSISTED') NOT NULL DEFAULT 'MANUAL',
  `ai_model` varchar(100) DEFAULT NULL,
  `prompt_version` varchar(50) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`concept_id`),
  UNIQUE KEY `uk_learning_concepts_code` (`concept_code`),
  UNIQUE KEY `uk_learning_concepts_slug` (`slug`),
  KEY `idx_learning_concepts_level` (`investment_level_id`,`status`,`sort_order`),
  KEY `idx_learning_concepts_topic` (`topic_id`,`status`,`sort_order`),
  CONSTRAINT `fk_learning_concepts_investment_level` FOREIGN KEY (`investment_level_id`) REFERENCES `investment_levels` (`investment_level_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_learning_concepts_topic` FOREIGN KEY (`topic_id`) REFERENCES `learning_topics` (`topic_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

