INSERT INTO `learning_concepts` VALUES (1,1,1,'BEGINNER_STOCK_OWNERSHIP','beginner-stock-ownership','주식과 주주의 의미','주식이 기업의 소유지분을 나타내는 증권이라는 뜻과 주주가 가지는 기본 권리, 주식 투자에 따르는 손익과 위험을 이해합니다.','[\"주식과 주주의 의미를 설명할 수 있다.\", \"주주와 채권자의 관계 차이를 구분할 수 있다.\", \"주식이 원금 보장 상품이 아닌 이유를 설명할 수 있다.\"]','별도의 선행 개념 없이 학습할 수 있습니다.',7,1,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(2,1,1,'BEGINNER_STOCK_PRICE_TRADING','beginner-stock-price-trading','주가와 주식 거래의 기본 구조','주가가 시장에서 어떻게 형성되는지, 매수·매도 주문과 호가·체결의 관계, 정보와 기대가 수요·공급을 바꾸는 과정을 이해합니다.','[\"주가와 체결가격의 의미를 설명할 수 있다.\", \"매수·매도와 호가·체결의 관계를 설명할 수 있다.\", \"시장가 주문과 지정가 주문의 기본 차이를 구분할 수 있다.\", \"정보와 기대 변화가 주가에 반영되는 과정을 설명할 수 있다.\"]','주식과 주주의 의미를 먼저 학습하면 이해하기 쉽습니다.',8,2,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(3,1,1,'BEGINNER_MARKET_CAP','beginner-market-cap','시가총액의 의미와 계산','주가와 상장주식 수를 이용해 시가총액을 계산하고, 한 주의 가격과 기업 지분 전체의 시장가치를 구분하는 방법을 배웁니다.','[\"시가총액의 의미를 설명할 수 있다.\", \"주가와 주식 수를 이용해 시가총액을 계산할 수 있다.\", \"주가만으로 기업 규모를 비교하면 안 되는 이유를 설명할 수 있다.\", \"시가총액과 기업가치(EV)가 같은 개념이 아님을 이해한다.\"]','주가와 주식의 기본 개념을 알고 있으면 좋습니다.',7,3,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(4,1,1,'BEGINNER_DIVIDEND','beginner-dividend','배당과 배당수익','기업이 주주에게 이익을 분배하는 배당의 기본 구조와 주당배당금·배당수익률, 시세차익과의 차이를 이해합니다.','[\"배당의 의미를 설명할 수 있다.\", \"주당배당금과 배당수익률을 구분할 수 있다.\", \"배당이 항상 지급되거나 유지되는 것은 아닌 이유를 설명할 수 있다.\"]','주식과 주주의 의미를 먼저 학습하면 이해하기 쉽습니다.',7,4,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(5,5,1,'BEGINNER_VOLUME_PRICE_FLOW','beginner-volume-price-flow','거래량과 가격 흐름','거래량과 거래대금의 차이를 이해하고, 거래량 변화를 가격 움직임과 함께 보는 기본적인 차트 해석 방법과 한계를 배웁니다.','[\"거래량과 거래대금의 차이를 설명할 수 있다.\", \"평소 거래량과 현재 거래량을 비교할 수 있다.\", \"가격과 거래량을 함께 보는 이유를 설명할 수 있다.\", \"거래량 해석이 확정적 매매신호가 아님을 이해한다.\"]','주가와 주식 거래의 기본 구조를 알고 있으면 좋습니다.',8,5,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(6,5,1,'BEGINNER_CANDLE_TREND','beginner-candle-trend','캔들차트와 기본 추세','캔들 하나에 담긴 시가·고가·저가·종가를 읽고 여러 기간의 고점과 저점 구조를 이용해 상승·하락·횡보 추세를 구분합니다.','[\"시가·고가·저가·종가를 설명할 수 있다.\", \"양봉과 음봉을 시가·종가 관계로 구분할 수 있다.\", \"고점과 저점의 흐름으로 기본 추세를 구분할 수 있다.\", \"한 캔들만으로 전체 추세를 확정하면 안 되는 이유를 이해한다.\"]','주가와 거래의 기본 구조를 먼저 학습하세요.',9,6,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(7,4,1,'BEGINNER_FINANCIAL_STATEMENTS_INTRO','beginner-financial-statements-intro','재무제표 입문','기업의 성과·재무상태·현금흐름을 보여주는 주요 재무제표와 매출액·영업이익·당기순이익, 자산·부채·자본의 기본 관계를 배웁니다.','[\"주요 재무제표가 각각 어떤 질문에 답하는지 구분할 수 있다.\", \"매출액·영업이익·당기순이익의 차이를 설명할 수 있다.\", \"자산·부채·자본의 기본 관계를 설명할 수 있다.\", \"재무제표 숫자는 주석과 기준을 함께 봐야 함을 이해한다.\"]','주식과 기업의 기본 개념을 알고 있으면 좋습니다.',9,7,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:32','2026-08-27 08:26:32'),(8,4,1,'BEGINNER_EPS','beginner-eps','EPS와 주당순이익','기업의 이익을 한 주 기준으로 환산한 EPS의 의미와 학습용 계산식, 실제 기본 EPS 산식에서 가중평균 유통보통주식수를 사용하는 이유를 배웁니다.','[\"EPS가 한 주 기준의 이익 지표임을 설명할 수 있다.\", \"StockMate 초급 문제에서 EPS를 계산할 수 있다.\", \"실제 기본 EPS 산식이 단순 발행주식 수와 다를 수 있음을 이해한다.\", \"주식 수 변화가 EPS에 영향을 줄 수 있음을 설명할 수 있다.\"]','재무제표 입문에서 당기순이익의 의미를 먼저 이해하세요.',8,8,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(9,2,1,'BEGINNER_PER','beginner-per','PER의 의미와 계산','주가가 주당이익의 몇 배 수준인지 보여주는 PER을 계산하고, 성장 기대·이익의 질·업종 차이를 함께 고려해 해석하는 기본 방법을 배웁니다.','[\"PER을 계산할 수 있다.\", \"높은 PER과 낮은 PER의 기본 의미를 설명할 수 있다.\", \"낮은 PER이 항상 저평가를 뜻하지 않는 이유를 설명할 수 있다.\", \"EPS가 음수이거나 일회성 이익이 큰 경우 PER 해석의 한계를 이해한다.\"]','EPS와 주당순이익을 먼저 학습하세요.',8,9,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(10,3,1,'BEGINNER_PBR_BPS','beginner-pbr-bps','PBR과 BPS','한 주당 장부상 순자산을 나타내는 BPS와 주가가 장부가치의 몇 배인지 보여주는 PBR의 기본 산식과 해석 한계를 배웁니다.','[\"BPS의 기본 의미를 설명할 수 있다.\", \"PBR을 계산할 수 있다.\", \"PBR 1배의 기본적인 의미를 설명할 수 있다.\", \"PBR 1배 미만이 항상 저평가를 뜻하지 않는 이유를 설명할 수 있다.\"]','재무제표 입문에서 자본의 의미를 먼저 학습하세요.',8,10,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(11,4,1,'BEGINNER_ROE','beginner-roe','ROE의 의미와 계산','기업이 자기자본을 활용해 얼마나 많은 이익을 냈는지 보여주는 ROE의 기본 계산과 평균 자기자본을 사용하는 실무적 해석을 배웁니다.','[\"ROE의 의미를 설명할 수 있다.\", \"StockMate 초급 문제에서 ROE를 계산할 수 있다.\", \"실제 분석에서 평균 자기자본을 사용하는 이유를 이해한다.\", \"높은 ROE의 원인을 부채·일회성 이익과 함께 확인할 수 있다.\"]','재무제표 입문에서 당기순이익과 자기자본을 먼저 학습하세요.',8,11,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(12,6,1,'BEGINNER_DEPOSIT_SAVINGS','beginner-deposit-savings','예금과 적금','예금과 적금의 납입 방식, 이자·만기·중도해지 구조를 비교하고 예금자보호 여부와 투자상품의 위험 차이를 이해합니다.','[\"예금과 적금의 납입 방식 차이를 설명할 수 있다.\", \"만기와 중도해지의 의미를 설명할 수 있다.\", \"표시금리만으로 실제 수령이자를 단순 비교하면 안 되는 이유를 이해한다.\", \"예금자보호 대상과 한도는 상품·제도 기준을 확인해야 함을 이해한다.\"]','별도의 선행 개념 없이 학습할 수 있습니다.',7,12,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(13,6,1,'BEGINNER_BOND','beginner-bond','채권의 기본 구조','채권이 발행자에게 자금을 빌려주는 증권이라는 구조를 이해하고 액면가·만기·쿠폰, 시장금리와 가격, 신용·유동성·물가 위험의 기본을 배웁니다.','[\"채권의 발행자·액면가·만기·쿠폰의 의미를 설명할 수 있다.\", \"일반적인 고정금리 채권에서 시장금리와 가격이 반대로 움직이는 이유를 설명할 수 있다.\", \"무이표채처럼 정기 쿠폰을 지급하지 않는 채권도 있음을 이해한다.\", \"채권의 신용위험·금리위험·유동성위험을 구분할 수 있다.\"]','예금과 적금의 기본 구조를 알고 있으면 비교하기 쉽습니다.',9,13,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(14,6,1,'BEGINNER_FUND_ETF','beginner-fund-etf','펀드와 ETF','여러 투자자의 자금을 모아 운용하는 펀드와 거래소에서 시장가격으로 거래되는 ETF의 구조를 비교하고 NAV·보수·괴리·추적오차의 기본을 배웁니다.','[\"펀드의 기본 구조를 설명할 수 있다.\", \"ETF와 일반 공모펀드의 거래방식 차이를 설명할 수 있다.\", \"NAV와 ETF 시장가격이 다를 수 있음을 이해한다.\", \"지수형 ETF의 추적오차와 상품별 위험을 설명할 수 있다.\"]','주식 거래와 분산투자의 기본 개념을 알고 있으면 좋습니다.',9,14,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(15,7,1,'BEGINNER_TOTAL_RETURN_COMPOUND_REAL','beginner-total-return-compound-real','투자 수익률·복리·실질수익률','가격 변화와 배당 등 현금수익을 포함한 총수익률, 기간이 이어질 때 복리로 누적되는 방식, 물가와 비용을 반영한 실질적인 투자성과를 이해합니다.','[\"기본 수익률과 총수익률을 구분할 수 있다.\", \"여러 기간의 수익률은 단순히 더하는 것이 아니라 복리로 누적됨을 설명할 수 있다.\", \"명목수익률과 물가를 반영한 실질수익률을 구분할 수 있다.\", \"수수료·세금이 실제 투자성과에 영향을 준다는 점을 이해한다.\"]','주가와 배당의 기본 개념을 먼저 학습하면 이해하기 쉽습니다.',9,15,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(16,7,1,'BEGINNER_RETURN_RISK_VOLATILITY','beginner-principal-loss-volatility','원금 손실과 변동성','평가손익과 실현손익, 손실 후 원금 회복에 필요한 수익률, 가격 변동의 크기를 뜻하는 변동성을 구분해 투자위험의 기본을 배웁니다.','[\"평가손익과 실현손익을 구분할 수 있다.\", \"손실률이 커질수록 원금 회복에 필요한 수익률이 더 커지는 이유를 설명할 수 있다.\", \"변동성과 손실을 같은 개념으로 보지 않을 수 있다.\", \"높은 변동성이 의미하는 위험을 설명할 수 있다.\"]','투자 수익률·복리·실질수익률을 먼저 학습하면 좋습니다.',8,16,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(17,7,1,'BEGINNER_DIVERSIFICATION_ALLOCATION','beginner-diversification-allocation','분산투자와 자산배분의 기초','여러 종목·업종·자산에 자금을 나누는 이유와 분산투자가 특정 위험을 줄일 수 있지만 손실을 보장 없이 없애지는 못한다는 점을 배웁니다.','[\"분산투자의 목적을 설명할 수 있다.\", \"종목 분산·업종 분산·자산 분산을 구분할 수 있다.\", \"종목 수가 많아도 같은 위험요인에 집중될 수 있음을 설명할 수 있다.\", \"자산배분이 투자목적·기간과 연결됨을 이해한다.\"]','원금 손실과 변동성의 기본 개념을 먼저 학습하세요.',8,17,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(18,1,1,'BEGINNER_MARKET_INDEX_SECTOR','beginner-market-index-sector','주식시장·시장지수·업종','개별 종목과 시장 전체를 구분하고 시장지수와 업종을 비교기준으로 활용해 기업 고유 요인과 시장·산업 공통 요인을 나누어 생각하는 방법을 배웁니다.','[\"개별 종목·업종·시장 전체의 범위를 구분할 수 있다.\", \"시장지수가 여러 종목의 움직임을 요약하는 기준임을 설명할 수 있다.\", \"같은 업종 기업을 비교하는 이유를 설명할 수 있다.\", \"종목 수익률을 시장·업종과 비교하는 기본 사고방식을 이해한다.\"]','주가와 시가총액의 기본 개념을 알고 있으면 좋습니다.',7,18,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(19,8,2,'INTERMEDIATE_FINANCIAL_LINK_STABILITY','intermediate-financial-link-stability','재무제표 연결과 재무 안정성','손익계산서의 이익과 재무상태표의 자금구조를 연결해 기업의 재무체력을 보고 부채 수준을 업종·현금흐름과 함께 해석하는 방법을 배웁니다.','[\"손익과 재무상태가 서로 다른 정보를 제공함을 설명할 수 있다.\", \"부채비율을 계산하고 기본 의미를 해석할 수 있다.\", \"부채가 많다는 사실만으로 위험을 확정하면 안 되는 이유를 설명할 수 있다.\", \"재무안정성을 업종·현금흐름·상환능력과 함께 볼 수 있다.\"]','초급 재무제표 입문, PBR, ROE를 학습한 뒤 보는 것을 권장합니다.',9,1,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(20,8,2,'INTERMEDIATE_EARNINGS_QUALITY_CASHFLOW','intermediate-earnings-quality-cashflow','이익의 질과 현금흐름','회계상 이익과 실제 현금흐름이 달라질 수 있는 이유를 이해하고 매출채권·재고자산·일회성 손익을 통해 이익의 지속 가능성을 점검합니다.','[\"순이익과 영업현금흐름의 차이를 설명할 수 있다.\", \"매출채권과 재고자산 증가를 현금흐름 관점에서 해석할 수 있다.\", \"일회성 손익과 반복 가능한 이익을 구분할 수 있다.\", \"영업현금흐름이 한 기간 음수라는 이유만으로 기업을 단정하면 안 되는 이유를 이해한다.\"]','재무제표 연결과 재무 안정성을 먼저 학습하세요.',10,2,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:33','2026-08-27 08:26:33'),(21,8,2,'INTERMEDIATE_PER_ROE','intermediate-per-roe','PER과 ROE를 함께 해석하기','기업의 이익 대비 가격 수준을 나타내는 PER과 자기자본 수익성을 나타내는 ROE를 함께 보면서 단일 지표의 한계를 줄이는 방법을 배웁니다.','[\"PER과 ROE가 서로 다른 정보를 제공함을 설명할 수 있다.\", \"낮은 PER과 높은 ROE의 조합을 해석할 수 있다.\", \"높은 ROE의 원인과 낮은 PER의 원인을 점검할 수 있다.\", \"동일 업종·기간·산식 기준으로 지표를 비교할 수 있다.\"]','초급 PER과 ROE를 먼저 학습하세요.',9,3,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(22,8,2,'INTERMEDIATE_GROWTH_PROFITABILITY','intermediate-growth-profitability','성장성과 수익성','매출 성장률과 영업이익률을 계산해 기업이 얼마나 성장하는지와 본업에서 얼마나 효율적으로 이익을 남기는지를 함께 해석합니다.','[\"매출 성장률을 계산할 수 있다.\", \"영업이익률을 계산할 수 있다.\", \"매출 성장과 수익성 변화가 서로 다른 방향으로 움직일 수 있음을 설명할 수 있다.\", \"기저효과·계절성·비교기간을 고려해 성장률을 해석할 수 있다.\"]','초급 재무제표 입문을 먼저 학습하세요.',9,4,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(23,5,2,'INTERMEDIATE_TREND_REVERSAL','intermediate-trend-reversal','추세의 지속과 전환','초급에서 배운 고점·저점 구조를 바탕으로 기존 추세가 유지되는지, 단기 반등인지, 구조적인 추세 전환 가능성이 커지는지 판단하는 방법을 배웁니다.','[\"추세 지속과 단기 반등을 구분할 수 있다.\", \"고점과 저점 구조 변화로 추세 전환 가능성을 판단할 수 있다.\", \"여러 시간 단위의 추세가 다를 수 있음을 설명할 수 있다.\", \"추세 분석이 미래 가격을 보장하지 않음을 이해한다.\"]','초급 캔들차트와 기본 추세를 먼저 학습하세요.',8,5,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(24,5,2,'INTERMEDIATE_SUPPORT_RESISTANCE_BREAKOUT','intermediate-support-resistance-breakout','지지·저항과 돌파','과거에 가격 반응이 반복된 지지·저항 구간을 찾고 돌파·이탈과 실패한 돌파를 종가·거래량과 함께 해석하는 방법을 배웁니다.','[\"지지와 저항의 의미를 가격 구간으로 설명할 수 있다.\", \"돌파와 이탈을 구분할 수 있다.\", \"실패한 돌파를 이후 가격흐름과 거래량으로 점검할 수 있다.\", \"지지·저항이 확정적 가격선이 아님을 이해한다.\"]','추세의 지속과 전환을 먼저 학습하세요.',9,6,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(25,5,2,'INTERMEDIATE_VOLUME_ADVANCED','intermediate-volume-advanced','거래량으로 가격 움직임 확인하기','평균 거래량과 현재 거래량을 비교해 돌파·조정·급락 구간에서 거래량이 가격 움직임의 신뢰도를 어떻게 보완하는지 배우고 한계를 이해합니다.','[\"평균 거래량과 현재 거래량을 비교할 수 있다.\", \"돌파·조정·급락에서 거래량 변화의 의미를 설명할 수 있다.\", \"거래량 급증의 원인이 매수 또는 매도 한쪽으로만 확정되지 않음을 이해한다.\", \"거래량을 단독 매매신호로 사용하지 않을 수 있다.\"]','초급 거래량과 가격 흐름, 중급 지지·저항을 먼저 학습하세요.',8,7,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(26,9,2,'INTERMEDIATE_MOVING_AVERAGE','intermediate-moving-average','이동평균선의 원리와 해석','일정 기간의 가격 평균을 연결한 이동평균선의 계산 원리와 SMA·EMA의 차이, 가격과 이동평균선의 위치·기울기를 해석하는 기본 방법과 후행성을 배웁니다.','[\"단순이동평균선(SMA)의 계산 원리를 설명할 수 있다.\", \"SMA와 EMA가 최근 가격을 반영하는 방식의 차이를 이해한다.\", \"가격과 이동평균선의 위치·기울기를 추세 보조근거로 해석할 수 있다.\", \"이동평균선이 후행지표라는 한계를 설명할 수 있다.\"]','초급 캔들차트와 기본 추세를 먼저 학습하세요.',9,8,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(27,9,2,'INTERMEDIATE_RSI','intermediate-rsi','RSI의 원리와 해석','상승과 하락의 상대적 강도를 0~100으로 나타내는 RSI의 계산 개념, 흔히 쓰이는 14기간·70/30 기준과 과매수·과매도 해석의 한계를 배웁니다.','[\"RSI가 상승·하락 강도의 상대적 비율을 나타내는 지표임을 설명할 수 있다.\", \"70·30 기준이 일반적인 참고값이지 절대 규칙이 아님을 이해한다.\", \"강한 추세에서 극단값이 오래 유지될 수 있음을 설명할 수 있다.\", \"다이버전스를 보조근거로만 사용할 수 있다.\"]','추세와 이동평균선의 기본 개념을 알고 있으면 좋습니다.',9,9,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(28,9,2,'INTERMEDIATE_MACD','intermediate-macd','MACD의 원리와 해석','단기와 장기 지수이동평균의 차이를 이용하는 MACD선, 시그널선과 히스토그램의 관계를 이해하고 12·26·9 대표 설정과 후행성의 한계를 배웁니다.','[\"MACD선이 두 이동평균의 차이를 이용한다는 점을 설명할 수 있다.\", \"시그널선과 히스토그램의 의미를 구분할 수 있다.\", \"0선과 선 교차를 모멘텀 보조근거로 해석할 수 있다.\", \"12·26·9는 대표 설정이며 변경 가능함을 이해한다.\"]','이동평균선의 원리를 먼저 학습하세요.',9,10,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(29,9,2,'INTERMEDIATE_BOLLINGER','intermediate-bollinger','볼린저밴드의 원리와 해석','이동평균과 표준편차를 이용해 가격의 상대적 위치와 변동성을 시각화하는 볼린저밴드의 대표 20기간·2표준편차 설정과 해석 한계를 배웁니다.','[\"볼린저밴드의 중심선·상단·하단을 설명할 수 있다.\", \"밴드 폭과 변동성의 관계를 설명할 수 있다.\", \"20기간 SMA와 ±2표준편차가 대표 설정임을 이해한다.\", \"밴드 접촉을 자동 매수·매도 신호로 보지 않을 수 있다.\"]','이동평균선과 변동성의 기본 개념을 알고 있으면 좋습니다.',9,11,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(30,10,2,'INTERMEDIATE_NEWS_REACTION','intermediate-news-reaction','뉴스 해석과 시장 반응','뉴스를 단순 호재·악재로 분류하지 않고 사실성과 출처, 기업 실적에 미칠 규모·기간, 시장의 기존 기대와 발표 뒤 실제 가격반응을 함께 분석합니다.','[\"뉴스의 사실·전망·루머를 구분할 수 있다.\", \"호재·악재를 기업 실적과 사업구조 기준으로 판단할 수 있다.\", \"좋은 뉴스와 주가 상승이 항상 일치하지 않는 이유를 설명할 수 있다.\", \"사건 발생일·보도일·시장 선반영을 구분할 수 있다.\"]','초급 주가와 시장지수·업종 개념을 먼저 학습하면 좋습니다.',10,12,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(31,11,2,'INTERMEDIATE_DISCLOSURE_EARNINGS','intermediate-disclosure-earnings','공시 기본과 실적 공시','기업이 공식적으로 제출하는 공시의 역할과 정정 가능성을 이해하고, 실적 공시에서 매출·영업이익·순이익, 기간 비교, 예상치와 일회성 요인을 읽는 방법을 배웁니다.','[\"공시와 언론 보도의 역할 차이를 설명할 수 있다.\", \"실적 공시에서 핵심 수치와 대상 기간을 확인할 수 있다.\", \"전년 동기·전분기 비교와 시장 예상치 차이를 해석할 수 있다.\", \"정정공시·주석·감사 또는 검토 범위를 함께 확인해야 함을 이해한다.\"]','초급 재무제표 입문과 중급 성장성·수익성을 먼저 학습하세요.',10,13,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(32,11,2,'INTERMEDIATE_CONTRACT_DISCLOSURE','intermediate-contract-disclosure','공급계약과 수주 공시','공급계약·수주 공시에서 계약금액을 회사 규모와 비교하고 계약기간·상대방·해지조건·실제 매출 인식 시점을 구분해 해석합니다.','[\"계약금액을 최근 매출 규모와 비교할 수 있다.\", \"계약 체결과 매출·이익 인식 시점을 구분할 수 있다.\", \"계약 상대방·기간·변경·해지 조건을 확인할 수 있다.\", \"계약금액 전체가 곧 순이익이라는 오해를 피할 수 있다.\"]','공시 기본과 실적 공시를 먼저 학습하세요.',9,14,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(33,11,2,'INTERMEDIATE_RIGHTS_OFFERING','intermediate-rights-offering','유상증자와 주식 희석','신주를 발행해 자금을 조달하는 유상증자의 구조를 이해하고 주주배정·제3자배정, 지분율 희석과 주당지표 희석을 구분하며 자금 사용 목적을 해석합니다.','[\"유상증자의 기본 구조를 설명할 수 있다.\", \"주주배정과 제3자배정의 차이를 기본 수준에서 설명할 수 있다.\", \"지분율 희석과 EPS 등 주당지표 희석을 구분할 수 있다.\", \"자금 사용 목적과 발행조건을 함께 확인할 수 있다.\"]','초급 주식·EPS·시가총액과 공시 기본을 먼저 학습하면 좋습니다.',10,15,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:34','2026-08-27 08:26:34'),(34,11,2,'INTERMEDIATE_DIVIDEND_DISCLOSURE','intermediate-dividend-disclosure','배당 공시 읽기','배당 공시에서 주당배당금·배당총액·기준일과 지급일을 확인하고 배당수익률·배당성향·현금흐름을 통해 지속 가능성을 판단하는 기본 방법을 배웁니다.','[\"배당 공시의 주요 항목을 찾을 수 있다.\", \"주당배당금과 배당수익률을 구분할 수 있다.\", \"배당성향의 기본 의미를 설명할 수 있다.\", \"배당의 지속 가능성을 이익·현금흐름·투자계획과 함께 볼 수 있다.\"]','초급 배당과 중급 이익의 질·현금흐름을 먼저 학습하면 좋습니다.',9,16,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:35','2026-08-27 08:26:35'),(35,12,2,'INTERMEDIATE_INDUSTRY_COMPARISON','intermediate-industry-comparison','같은 업종 기업 종합 비교','같은 업종 기업의 성장성·수익성·밸류에이션·재무안정성·현금흐름과 비재무 경쟁력을 동일 기준으로 비교하고 장점과 위험을 종합하는 방법을 배웁니다.','[\"같은 업종 기업을 비교하는 이유를 설명할 수 있다.\", \"성장성·수익성·밸류에이션·안정성을 동일 기준으로 비교할 수 있다.\", \"시장점유율·연구개발·해외매출 등 비재무 요소를 고려할 수 있다.\", \"한 지표만으로 기업 우열을 확정하지 않을 수 있다.\"]','중급 재무분석 파트와 초급 시장지수·업종을 학습한 뒤 보는 것을 권장합니다.',11,17,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:35','2026-08-27 08:26:35'),(36,7,2,'INTERMEDIATE_CORRELATION_DIVERSIFICATION','intermediate-correlation-diversification','상관관계와 분산투자의 한계','자산 수익률이 함께 움직이는 정도를 나타내는 상관관계의 양·음·0 개념을 이해하고, 종목 수가 많아도 공통 위험요인이 크면 분산효과가 제한될 수 있음을 배웁니다.','[\"양의 상관·음의 상관·0에 가까운 상관을 구분할 수 있다.\", \"상관계수의 범위와 기본 의미를 설명할 수 있다.\", \"표면적인 종목 수와 실제 위험 분산이 다를 수 있음을 설명할 수 있다.\", \"과거 상관관계가 미래에도 고정되지 않음을 이해한다.\"]','초급 분산투자와 자산배분의 기초를 먼저 학습하세요.',9,18,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:35','2026-08-27 08:26:35'),(37,13,2,'INTERMEDIATE_INVESTOR_PROFILE_ALLOCATION','intermediate-investor-profile-allocation','투자 성향과 목적에 맞는 상품 구성','StockMate 학습용 안정형·성장형·공격형 분류를 통해 위험 선호를 이해하고 실제 자산구성에서는 투자목적·기간·유동성·손실감당능력을 별도로 고려해야 함을 배웁니다.','[\"StockMate의 안정형·성장형·공격형 학습 분류를 구분할 수 있다.\", \"위험을 감수하고 싶은 의향과 실제 손실 감당 능력을 구분할 수 있다.\", \"투자목적·기간·비상자금에 따라 상품 역할이 달라짐을 설명할 수 있다.\", \"성향 등급이 특정 상품의 적합성이나 수익을 보장하지 않음을 이해한다.\"]','초급 금융상품, 투자 위험, 분산투자를 모두 학습한 뒤 보는 것을 권장합니다.',10,19,NULL,'DRAFT','AI_ASSISTED',NULL,'concept-37-reviewed-v2',2,'2026-08-27 08:26:35','2026-08-27 08:26:35');
