--
-- Table structure for table `quiz_questions`
--

DROP TABLE IF EXISTS `quiz_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz_questions` (
  `question_id` int NOT NULL AUTO_INCREMENT,
  `topic_id` int NOT NULL,
  `investment_level_id` int DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `owner_user_id` int DEFAULT NULL,
  `source_type` enum('DEFAULT','WRONG_ANSWER','PERSONAL_PROMPT','ADMIN') NOT NULL DEFAULT 'DEFAULT',
  `quiz_pool_type` enum('GENERAL','CONCEPT_CHECK','BOTH') NOT NULL DEFAULT 'GENERAL',
  `visibility` enum('PUBLIC','PRIVATE') NOT NULL DEFAULT 'PUBLIC',
  `source_question_id` int DEFAULT NULL,
  `source` enum('MANUAL','AI') NOT NULL DEFAULT 'MANUAL',
  `review_status` enum('PENDING','ACTIVE','INACTIVE','REJECTED','REVIEW_REQUIRED') NOT NULL DEFAULT 'ACTIVE',
  `ai_quality_score` int DEFAULT NULL,
  `final_quality_score` int DEFAULT NULL,
  `similarity_score` decimal(5,4) DEFAULT NULL,
  `similar_question_id` int DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `question_type` enum('MULTIPLE_CHOICE','OX') NOT NULL,
  `question_text` text NOT NULL,
  `explanation` text,
  `reward_cash` int DEFAULT '0',
  `status` enum('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`question_id`),
  KEY `idx_quiz_topic` (`topic_id`),
  KEY `idx_quiz_level` (`investment_level_id`),
  KEY `idx_quiz_category` (`category_id`),
  KEY `idx_quiz_owner` (`owner_user_id`),
  KEY `idx_quiz_visibility_status` (`visibility`,`status`),
  KEY `idx_quiz_owner_visibility_status` (`owner_user_id`,`visibility`,`status`),
  KEY `idx_quiz_source_type` (`source_type`),
  KEY `idx_quiz_pool_type` (`quiz_pool_type`,`status`,`review_status`),
  KEY `idx_quiz_source_question` (`source_question_id`),
  KEY `idx_quiz_questions_review_status` (`review_status`),
  KEY `idx_quiz_questions_source` (`source`),
  KEY `idx_quiz_questions_quality` (`final_quality_score`,`similarity_score`),
  KEY `idx_quiz_status` (`status`),
  CONSTRAINT `fk_quiz_questions_category` FOREIGN KEY (`category_id`) REFERENCES `quiz_categories` (`category_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quiz_questions_investment_level` FOREIGN KEY (`investment_level_id`) REFERENCES `investment_levels` (`investment_level_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quiz_questions_owner` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_quiz_questions_source_question` FOREIGN KEY (`source_question_id`) REFERENCES `quiz_questions` (`question_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quiz_questions_topic` FOREIGN KEY (`topic_id`) REFERENCES `learning_topics` (`topic_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=952 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

