-- Dumping data for table `quiz_questions`
--

LOCK TABLES `quiz_questions` WRITE;
/*!40000 ALTER TABLE `quiz_questions` DISABLE KEYS */;
INSERT INTO `quiz_questions` VALUES (3,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','\'주식\'의 의미로 가장 적절한 것은?','개념 \'주식\'는 기업의 소유권 일부를 나타내는 증권이다. 다른 보기는 같은 카테고리의 다른 개념이거나 투자 위험을 과도하게 단순화한 설명이다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(4,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','다음 설명에 해당하는 용어는 무엇인가? “기업의 소유권 일부를 나타내는 증권”','제시된 설명은 \'주식\'의 정의에 해당한다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(5,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','\'주식\'에 대한 설명 중 가장 타당한 것은?','\'주식\'의 의미는 기업의 소유권 일부를 나타내는 증권이며, 하나의 정보만으로 수익이나 손실을 확정할 수 없다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(6,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','개념 \'주식\'와 용어 \'거래량\'를 올바르게 구분한 설명은?','두 개념은 목적과 계산 방식이 다르다. 개념 \'주식\'는 기업의 소유권 일부를 나타내는 증권이고 개념 \'거래량\'는 일정 기간 실제로 거래된 주식 수량이다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(7,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','개념 \'주식\'는 기업의 소유권 일부를 나타내는 증권이다.','맞다. \'주식\'의 기본 정의는 기업의 소유권 일부를 나타내는 증권이다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(8,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','용어 \'주식\'를 확인하면 투자 손실이 발생하지 않는다고 단정할 수 있다.','틀리다. 개념 \'주식\'는 기업의 소유권 일부를 나타내는 증권이지만 투자 손실을 보장하거나 제거하지 않는다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(9,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','투자자가 개념 \'주식\'와 관련된 정보를 확인했다. 다음 행동 중 가장 바람직한 것은?','개념 \'주식\'는 기업의 소유권 일부를 나타내는 증권이다. 실제 판단에서는 단일 정보가 아니라 목적·기간·위험을 함께 고려해야 한다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(10,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','다음 중 \'주식\'에 관한 올바른 설명은?','정답은 정의에 부합한다. 나머지 보기는 보장·확정 표현을 사용해 개념의 한계를 벗어난다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(11,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기본 개념을 확인한다. \'주식\'의 의미로 가장 적절한 것은?','개념 \'주식\'는 기업의 소유권 일부를 나타내는 증권이다. 다른 보기는 같은 카테고리의 다른 개념이거나 투자 위험을 과도하게 단순화한 설명이다.',1000,'ACTIVE','2026-08-24 08:46:23','2026-08-24 08:46:23'),(12,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기본 개념을 확인한다. 다음 설명에 해당하는 용어는 무엇인가? “기업의 소유권 일부를 나타내는 증권”','제시된 설명은 \'주식\'의 정의에 해당한다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(13,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','\'주가\'의 의미로 가장 적절한 것은?','개념 \'주가\'는 시장에서 거래되는 주식 한 주의 가격이다. 다른 보기는 같은 카테고리의 다른 개념이거나 투자 위험을 과도하게 단순화한 설명이다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(14,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','다음 설명에 해당하는 용어는 무엇인가? “시장에서 거래되는 주식 한 주의 가격”','제시된 설명은 \'주가\'의 정의에 해당한다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(15,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','\'주가\'에 대한 설명 중 가장 타당한 것은?','\'주가\'의 의미는 시장에서 거래되는 주식 한 주의 가격이며, 하나의 정보만으로 수익이나 손실을 확정할 수 없다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(16,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','개념 \'주가\'와 용어 \'시가총액\'를 올바르게 구분한 설명은?','두 개념은 목적과 계산 방식이 다르다. 개념 \'주가\'는 시장에서 거래되는 주식 한 주의 가격이고 개념 \'시가총액\'는 주가와 발행주식 수를 곱한 기업 가치 규모이다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(17,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','개념 \'주가\'는 시장에서 거래되는 주식 한 주의 가격이다.','맞다. \'주가\'의 기본 정의는 시장에서 거래되는 주식 한 주의 가격이다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(18,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','용어 \'주가\'를 확인하면 투자 손실이 발생하지 않는다고 단정할 수 있다.','틀리다. 개념 \'주가\'는 시장에서 거래되는 주식 한 주의 가격이지만 투자 손실을 보장하거나 제거하지 않는다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(19,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','투자자가 개념 \'주가\'와 관련된 정보를 확인했다. 다음 행동 중 가장 바람직한 것은?','개념 \'주가\'는 시장에서 거래되는 주식 한 주의 가격이다. 실제 판단에서는 단일 정보가 아니라 목적·기간·위험을 함께 고려해야 한다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(20,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','다음 중 \'주가\'에 관한 올바른 설명은?','정답은 정의에 부합한다. 나머지 보기는 보장·확정 표현을 사용해 개념의 한계를 벗어난다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(21,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기본 개념을 확인한다. \'주가\'의 의미로 가장 적절한 것은?','개념 \'주가\'는 시장에서 거래되는 주식 한 주의 가격이다. 다른 보기는 같은 카테고리의 다른 개념이거나 투자 위험을 과도하게 단순화한 설명이다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(22,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기본 개념을 확인한다. 다음 설명에 해당하는 용어는 무엇인가? “시장에서 거래되는 주식 한 주의 가격”','제시된 설명은 \'주가\'의 정의에 해당한다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(23,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','\'시가총액\'의 의미로 가장 적절한 것은?','개념 \'시가총액\'는 주가와 발행주식 수를 곱한 기업 가치 규모이다. 다른 보기는 같은 카테고리의 다른 개념이거나 투자 위험을 과도하게 단순화한 설명이다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(24,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','다음 설명에 해당하는 용어는 무엇인가? “주가와 발행주식 수를 곱한 기업 가치 규모”','제시된 설명은 \'시가총액\'의 정의에 해당한다.',1000,'ACTIVE','2026-08-24 08:46:24','2026-08-24 08:46:24'),(25,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','A